BEGIN;
CREATE FUNCTION pg_temp.doc_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION '%',message; END IF; END $$;
CREATE FUNCTION pg_temp.doc_denied(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE '%'||expected||'%' THEN RETURN; ELSE RAISE; END IF; END; RAISE EXCEPTION 'Expected denial: %',statement; END $$;
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES
 ('00000000-0000-4000-9050-000000000001','owner50@example.test',now()),('00000000-0000-4000-9050-000000000002','other50@example.test',now()),('00000000-0000-4000-9050-000000000003','staff50@example.test',now());
INSERT INTO user_roles(user_id,role) VALUES('00000000-0000-4000-9050-000000000001','owner'),('00000000-0000-4000-9050-000000000002','owner'),('00000000-0000-4000-9050-000000000003','admin');
INSERT INTO property_owners(id,name,active) VALUES('00000000-0000-4000-9050-000000000011','Owner50',true),('00000000-0000-4000-9050-000000000012','Other50',true);
INSERT INTO properties(id,name,owner_record_id,is_demo) VALUES('00000000-0000-4000-9050-000000000021','Home50','00000000-0000-4000-9050-000000000011',false);
SELECT set_config('test.actor','00000000-0000-4000-9050-000000000003',true);
INSERT INTO owner_programs(id,property_id,owner_record_id,owner_user_id,status,is_demo) VALUES('00000000-0000-4000-9050-000000000031','00000000-0000-4000-9050-000000000021','00000000-0000-4000-9050-000000000011','00000000-0000-4000-9050-000000000001','draft',false);
INSERT INTO owner_program_properties(program_id,property_id,inclusion_status,closing_date,closing_confirmed) VALUES('00000000-0000-4000-9050-000000000031','00000000-0000-4000-9050-000000000021','included',current_date,true);
INSERT INTO documents(id,entity_type,entity_id,property_id,visibility,title,note,uploaded_by) VALUES('00000000-0000-4000-9050-000000000041','property','00000000-0000-4000-9050-000000000021','00000000-0000-4000-9050-000000000021','owner_shared','Legacy','PRIVATE staff notes','00000000-0000-4000-9050-000000000001');
SELECT set_config('test.actor','00000000-0000-4000-9050-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.doc_assert((SELECT count(*) FROM documents)=0,'Raw document SELECT remains exposed');
UPDATE documents SET note='owner rewrote staff notes' WHERE id='00000000-0000-4000-9050-000000000041';
SELECT pg_temp.doc_assert(NOT owner_document_access('00000000-0000-4000-9050-000000000041'),'Unbound legacy share granted owner access');
SELECT pg_temp.doc_denied($q$SELECT request_owner_document('00000000-0000-4000-9050-000000000003','{}')$q$,'permission denied');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT note='PRIVATE staff notes' FROM documents WHERE id='00000000-0000-4000-9050-000000000041'),'Owner whole-row UPDATE survived');
SET LOCAL ROLE service_role;
SELECT set_attachment_visibility('00000000-0000-4000-9050-000000000003','00000000-0000-4000-9050-000000000041','owner_shared');
SELECT pg_temp.doc_assert(owner_document_access('00000000-0000-4000-9050-000000000041','00000000-0000-4000-9050-000000000001'),'Explicit canonical share denied');
SELECT pg_temp.doc_assert(NOT owner_document_access('00000000-0000-4000-9050-000000000041','00000000-0000-4000-9050-000000000002'),'Other owner received share');
SELECT set_config('test.doc_request',request_owner_document('00000000-0000-4000-9050-000000000003','{"entityType":"property","entityId":"00000000-0000-4000-9050-000000000021","title":"Recorded deed","note":"Please supply the deed"}')::text,true);
SELECT set_config('test.doc_input',jsonb_build_object('entityType','property','entityId','00000000-0000-4000-9050-000000000021','uploadKey','00000000-0000-4000-9050-000000000051','filename','deed.pdf','mimeType','application/pdf','sizeBytes',1024,'kind','document','path','property/00000000-0000-4000-9050-000000000021/00000000-0000-4000-9050-000000000051-deed.pdf','fulfilsRequestId',current_setting('test.doc_request'))::text,true);
SELECT set_config('test.doc_upload',(begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb)->>'documentId'),true);
-- A second attempt can exist, but only one can fulfill the original request.
SELECT set_config('test.doc_competing',(begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb||'{"uploadKey":"00000000-0000-4000-9050-000000000052","path":"property/00000000-0000-4000-9050-000000000021/00000000-0000-4000-9050-000000000052-deed.pdf"}')->>'documentId'),true);
SELECT pg_temp.doc_assert((begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb)->>'documentId')=current_setting('test.doc_upload'),'Begin retry duplicated intent');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb||'{"sizeBytes":2048}')$q$,'different or completed');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000003',current_setting('test.doc_input')::jsonb)$q$,'different or completed');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000002',current_setting('test.doc_input')::jsonb)$q$,'access denied');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb||'{"filename":"different.pdf"}')$q$,'different or completed');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb||'{"mimeType":"text/plain"}')$q$,'different or completed');
SELECT pg_temp.doc_denied($q$SELECT begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb||'{"fulfilsRequestId":null}')$q$,'different or completed');
SELECT pg_temp.doc_denied($q$SELECT complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,true,'00000000-0000-4000-9050-000000000041')$q$,'Original document request');
SELECT pg_temp.doc_denied($q$UPDATE documents SET fulfils_request_id=NULL WHERE id=current_setting('test.doc_upload')::uuid$q$,'checked document');
RESET ROLE;
-- Failure in history must roll back both the file and its original request.
CREATE FUNCTION pg_temp.fail_doc_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='attachment.uploaded' THEN RAISE EXCEPTION 'injected document history failure'; END IF;RETURN NEW; END $$;
CREATE TRIGGER fail_doc_audit BEFORE INSERT ON audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_doc_audit();
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_denied($q$SELECT complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,true)$q$,'injected document history failure');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT bool_and(upload_status='pending') FROM documents WHERE id IN(current_setting('test.doc_upload')::uuid,current_setting('test.doc_request')::uuid)),'Partial upload/request completion survived history failure');
DROP TRIGGER fail_doc_audit ON audit_log;
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,true),'Completion failed');
SELECT pg_temp.doc_assert(complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,true),'Stored receipt retry failed');
SELECT pg_temp.doc_denied($q$SELECT complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_competing')::uuid,true)$q$,'Original document request is no longer open');
SELECT pg_temp.doc_assert((begin_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_input')::jsonb)->>'alreadyStored')::boolean,'Begin lost stored receipt');
SELECT pg_temp.doc_denied($q$SELECT complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,false)$q$,'no longer pending');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT fulfilled_by_document_id=current_setting('test.doc_upload')::uuid AND upload_status='stored' FROM documents WHERE id=current_setting('test.doc_request')::uuid),'Original request receipt missing');
SELECT pg_temp.doc_assert((SELECT count(*) FROM audit_log WHERE action='attachment.uploaded' AND after_value->>'documentId'=current_setting('test.doc_upload'))=1,'Duplicate completion history');
SELECT pg_temp.doc_denied($q$UPDATE documents SET storage_path='rewritten' WHERE id=current_setting('test.doc_upload')::uuid$q$,'immutable');
SELECT pg_temp.doc_denied($q$UPDATE documents SET note='Changed after owner uploaded' WHERE id=current_setting('test.doc_request')::uuid$q$,'Original owner document request is immutable');
SELECT pg_temp.doc_denied($q$UPDATE documents SET upload_status='pending',fulfilled_by_document_id=NULL WHERE id=current_setting('test.doc_request')::uuid$q$,'completion receipt is immutable');
SELECT pg_temp.doc_denied($q$UPDATE document_recipient_events SET event='unshared'$q$,'append-only');
SELECT pg_temp.doc_assert((SELECT upload_status='pending' FROM documents WHERE id=current_setting('test.doc_competing')::uuid),'Competing request completion partially committed');
-- Actual account/role revocation affects direct scope and checked writes.
DELETE FROM user_roles WHERE user_id='00000000-0000-4000-9050-000000000001';
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000001'),'Revoked owner retained document access');
SELECT pg_temp.doc_denied($q$SELECT complete_attachment_upload('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,true)$q$,'access denied');
RESET ROLE;
INSERT INTO user_roles(user_id,role) VALUES('00000000-0000-4000-9050-000000000001','owner'),('00000000-0000-4000-9050-000000000001','vendor');
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000001'),'Mixed external role retained owner document access');
RESET ROLE;
DELETE FROM user_roles WHERE user_id='00000000-0000-4000-9050-000000000001' AND role='vendor';
UPDATE auth.users SET banned_until=now()+interval '1 day' WHERE id='00000000-0000-4000-9050-000000000001';
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000001'),'Banned owner retained access');
RESET ROLE;
UPDATE auth.users SET banned_until=NULL WHERE id='00000000-0000-4000-9050-000000000001';
SELECT set_config('test.actor','00000000-0000-4000-9050-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.doc_assert((SELECT count(*) FROM documents)>0,'Staff document read lost');
UPDATE documents SET note='Updated staff notes' WHERE id='00000000-0000-4000-9050-000000000041';
SELECT pg_temp.doc_denied($q$UPDATE documents SET visibility='internal' WHERE id='00000000-0000-4000-9050-000000000041'$q$,'checked document sharing');
RESET ROLE;
CREATE OR REPLACE FUNCTION pg_temp.fail_doc_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='attachment.removed' THEN RAISE EXCEPTION 'injected removal history failure'; END IF;RETURN NEW; END $$;
CREATE TRIGGER fail_doc_audit BEFORE INSERT ON audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_doc_audit();
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_denied($q$SELECT archive_attachment('00000000-0000-4000-9050-000000000003','00000000-0000-4000-9050-000000000041','Superseded evidence')$q$,'injected removal history failure');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT deleted_at IS NULL FROM documents WHERE id='00000000-0000-4000-9050-000000000041'),'Removal survived failed history');
DROP TRIGGER fail_doc_audit ON audit_log;
UPDATE auth.users SET banned_until=now()+interval '1 day' WHERE id='00000000-0000-4000-9050-000000000003';
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_denied($q$SELECT archive_attachment('00000000-0000-4000-9050-000000000003','00000000-0000-4000-9050-000000000041',NULL)$q$,'Active account required');
SELECT pg_temp.doc_denied($q$SELECT archive_attachment('00000000-0000-4000-9050-000000000001',current_setting('test.doc_upload')::uuid,NULL)$q$,'Staff access required');
RESET ROLE;
UPDATE auth.users SET banned_until=NULL WHERE id='00000000-0000-4000-9050-000000000003';
UPDATE documents SET storage_path='retained/legacy.pdf' WHERE id='00000000-0000-4000-9050-000000000041';
SET LOCAL ROLE service_role;
SELECT archive_attachment('00000000-0000-4000-9050-000000000003','00000000-0000-4000-9050-000000000041','Superseded evidence');
SELECT archive_attachment('00000000-0000-4000-9050-000000000003','00000000-0000-4000-9050-000000000041','Idempotent retry');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT deleted_at IS NOT NULL AND storage_path='retained/legacy.pdf' FROM documents WHERE id='00000000-0000-4000-9050-000000000041'),'Soft removal erased evidence storage identity');
SELECT pg_temp.doc_assert((SELECT count(*) FROM audit_log WHERE action='attachment.removed' AND after_value->>'documentId'='00000000-0000-4000-9050-000000000041')=1,'Removal retry duplicated history');
-- Archive/removal and transfer retain historical recipients but revoke access.
UPDATE owner_program_properties SET archived_at=now() WHERE program_id='00000000-0000-4000-9050-000000000031';
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000001'),'Archived enrollment retained access');
RESET ROLE;
UPDATE properties SET owner_record_id='00000000-0000-4000-9050-000000000012' WHERE id='00000000-0000-4000-9050-000000000021';
SELECT pg_temp.doc_assert((SELECT owner_recipient_id='00000000-0000-4000-9050-000000000011' FROM documents WHERE id=current_setting('test.doc_upload')::uuid),'Transfer rewrote original intended owner');
SELECT pg_temp.doc_assert((SELECT count(*) FROM document_recipient_events WHERE document_id=current_setting('test.doc_upload')::uuid)=2,'Recipient history disappeared');
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000002'),'Transfer leaked prior owner upload');
SELECT pg_temp.doc_denied($q$SELECT set_attachment_visibility('00000000-0000-4000-9050-000000000003',current_setting('test.doc_upload')::uuid,'owner_shared')$q$,'exactly one current canonical');
RESET ROLE;
-- New enrollment grants no old share until an explicit reviewed re-share.
INSERT INTO owner_programs(id,property_id,owner_record_id,owner_user_id,status,is_demo) VALUES('00000000-0000-4000-9050-000000000032','00000000-0000-4000-9050-000000000021','00000000-0000-4000-9050-000000000012','00000000-0000-4000-9050-000000000002','draft',false);
INSERT INTO owner_program_properties(program_id,property_id,inclusion_status,closing_date,closing_confirmed) VALUES('00000000-0000-4000-9050-000000000032','00000000-0000-4000-9050-000000000021','included',current_date,true);
SET LOCAL ROLE service_role;
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000002'),'New canonical enrollment inherited old recipient share');
SELECT pg_temp.doc_denied($q$SELECT set_attachment_visibility('00000000-0000-4000-9050-000000000003',current_setting('test.doc_competing')::uuid,'owner_shared')$q$,'Complete the original upload');
SELECT set_attachment_visibility('00000000-0000-4000-9050-000000000003',current_setting('test.doc_upload')::uuid,'owner_shared');
SELECT pg_temp.doc_assert(owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000002'),'Explicit reviewed re-share did not grant new owner');
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000001'),'Prior recipient retained access after re-share');
SELECT set_attachment_visibility('00000000-0000-4000-9050-000000000003',current_setting('test.doc_upload')::uuid,'internal');
SELECT pg_temp.doc_assert(NOT owner_document_access(current_setting('test.doc_upload')::uuid,'00000000-0000-4000-9050-000000000002'),'Unshare did not revoke new recipient');
RESET ROLE;
SELECT pg_temp.doc_assert((SELECT count(*) FROM document_recipient_events WHERE document_id=current_setting('test.doc_upload')::uuid AND owner_id='00000000-0000-4000-9050-000000000011')=2,'Re-share rewrote prior recipient history');
ROLLBACK;
